// @vitest-environment happy-dom
// Spec: k.testing, Conformance "The same page without `app` records no document on a submit, and the `keel.fields` answer sets the field's error in process."
// Spec: k.testing, Harness "Without `app` a router renders; a submit runs in process."
// Seed: 1337 (fc.assert below). Unlike the `app` cases this passes today (no `app` option involved); it is skipped only until the ledger row k.testing#17 is regenerated by the builder. See render-route-document-support.ts.
import { renderRoute } from "@keel/testing";
import fc from "fast-check";
import { expect, test } from "vitest";
import { MESSAGE, SEED, control, reset, routes, simCtx } from "./render-route-document-support.ts";

test("The same page without `app` records no document on a submit, and the `keel.fields` answer sets the field's error in process.", async () => {
  await fc.assert(
    fc.asyncProperty(fc.stringMatching(/^[a-z]{1,8}$/), async (value) => {
      reset("fields");
      const h = await renderRoute("f.page", { routes, ctx: simCtx() });
      await h.fire("f.amount", { type: "input", value });
      await h.fire("f.save", { type: "click" });
      expect(h.documents()).toEqual([]);
      expect(control.posts).toBe(1);
      expect(h.find("f.error").text).toBe(MESSAGE);
      expect(h.a11y("f.amount").state.invalid).toBe(true);
      h.dispose();
    }),
    { seed: SEED, numRuns: 10 },
  );
});
